// Recognizers often write small numbers as digits ("7"), while prompts spell them out.
const numberWords =
  "zero one two three four five six seven eight nine ten eleven twelve".split(
    " ",
  );
const normalize = (text: string) =>
  text
    .toLowerCase()
    .replace(/[’']/g, "'")
    .replace(/[^a-z0-9' ]+/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .map((word) =>
      /^\d+$/.test(word) ? (numberWords[Number(word)] ?? word) : word,
    );

// Compares the recognizer's transcript with the target sentence word by word. It shows which
// words the browser's speech recognizer heard; it does not measure pronunciation quality.
export function compareWords(target: string, transcript: string) {
  const heard = normalize(transcript);
  const remaining = new Map<string, number>();
  for (const word of heard) remaining.set(word, (remaining.get(word) ?? 0) + 1);
  const words = target.split(/\s+/).map((display) => {
    const [key] = normalize(display);
    const count = key ? (remaining.get(key) ?? 0) : 0;
    if (count > 0) remaining.set(key, count - 1);
    return { display, heard: !key || count > 0 };
  });
  return {
    words,
    matched: words.filter((w) => w.heard).length,
    total: words.length,
  };
}
